def fetch_username(eos):
    try:
        r = requests.get(f"{BACKEND_API}/user/username",
                         headers={"Authorization": "Bearer " + eos["id_token"], **BACKEND_HEADERS},
                         timeout=15)
        if r.status_code == 200:
            attrs = r.json().get("data", {}).get("attributes", {})
